{"file_path":"src/parse.js","content":"// Parses election input text into { candidates, ballots }.
// Throws an Error whose message is the text that follows "error: " in the
// specified diagnostic (with or without a leading "line N: ").

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

function fail(lineNo, message) {
  throw new Error(`line ${lineNo}: ${message}`)
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail(lineNo, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(lineNo, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          fail(lineNo, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (word === 'ballot') {
      if (candidates === null) {
        fail(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        fail(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countText = tokens[1]
      if (!COUNT_RE.test(countText)) {
        fail(lineNo, 'count must be a positive integer')
      }
      const count = Number(countText)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(lineNo, `unknown directive ${word}`)
    }
  }

  if (candidates === null) {
    throw new Error('no candidates')
  }

  return { candidates, ballots }
}
"}

