{"file_path":"src/tally.js","content":"// Runs the instant-runoff count described in the specification.
//
// Returns an array of round records:
//   { votes: [{ name, count }...] (continuing candidates, unsorted),
//     exhausted: number,
//     eliminated: string | null,
//     winner: string | null,
//     noWinner: boolean }
// The last record has either `winner` set, `noWinner` true, or neither only
// if this were an infinite process (never happens: the loop always ends).

function resolveTie(tiedNames, histories) {
  let cands = tiedNames.slice()
  while (true) {
    let foundDiff = false
    for (let r = 0; r < histories.length; r++) {
      const counts = cands.map((n) => histories[r].get(n))
      const min = Math.min(...counts)
      const survivors = cands.filter((n) => histories[r].get(n) === min)
      if (survivors.length < cands.length) {
        cands = survivors
        foundDiff = true
        break
      }
    }
    if (!foundDiff) break
    if (cands.length === 1) return cands[0]
  }
  let last = cands[0]
  for (const n of cands) if (n > last) last = n
  return last
}

export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const totalBallots = ballots.reduce((sum, b) => sum + b.count, 0)
  const histories = []
  const rounds = []

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    for (const ballot of ballots) {
      const chosen = ballot.names.find((n) => continuing.has(n))
      if (chosen !== undefined) votes.set(chosen, votes.get(chosen) + ballot.count)
    }
    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)
    const exhausted = totalBallots - activeTotal
    histories.push(votes)

    const voteList = [...votes.entries()].map(([name, count]) => ({ name, count }))

    if (activeTotal === 0) {
      rounds.push({ votes: voteList, exhausted, eliminated: null, winner: null, noWinner: true })
      break
    }

    let winner = null
    for (const { name, count } of voteList) {
      if (count * 2 > activeTotal) { winner = name; break }
    }
    if (winner !== null) {
      rounds.push({ votes: voteList, exhausted, eliminated: null, winner, noWinner: false })
      break
    }

    const minCount = Math.min(...voteList.map((v) => v.count))
    const tied = voteList.filter((v) => v.count === minCount).map((v) => v.name)
    const eliminated = tied.length === 1 ? tied[0] : resolveTie(tied, histories)
    continuing.delete(eliminated)
    rounds.push({ votes: voteList, exhausted, eliminated, winner: null, noWinner: false })
  }

  return rounds
}
"}

