{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parse.js'
import { runElection } from './tally.js'

function formatRoundLine(roundNo, round) {
  const sorted = round.votes.slice().sort((a, b) => {
    if (b.count !== a.count) return b.count - a.count
    return a.name < b.name ? -1 : a.name > b.name ? 1 : 0
  })
  const parts = sorted.map((v) => `${v.name}=${v.count}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${roundNo}: ${parts.join(' ')}`
}

function outcomeLine(rounds) {
  const last = rounds[rounds.length - 1]
  return last.winner !== null ? `winner ${last.winner}` : 'no winner'
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]

  const chunks = []
  process.stdin.on('data', (c) => chunks.push(c))
  process.stdin.on('end', () => {
    const input = Buffer.concat(chunks).toString('utf8')
    let election
    try {
      election = parseElection(input)
    } catch (e) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exitCode = 2
      return
    }

    const rounds = runElection(election.candidates, election.ballots)
    const lines = []
    if (mode === 'rounds') {
      rounds.forEach((round, idx) => {
        lines.push(formatRoundLine(idx + 1, round))
        if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
      })
    } else {
      lines.push(`rounds ${rounds.length}`)
    }
    lines.push(outcomeLine(rounds))
    process.stdout.write(lines.join('\n') + '\n')
  })
}

main()
"}

